SELECT day.ssp_slot_id AS ssp_slot_id, day.date AS date, SUM(day.show_pv) AS show_pv, SUM(day.click_pv) AS click_pv, SUM(day.req_count) AS req_pv, SUM(day.discard) AS discard, SUM(day.ret_pv) AS ret_pv, SUM(day.spend) AS spend, SUM(day.income) AS income, SUM(day.discount_click_pv) AS discount_click_pv, SUM(day.discount_show_pv) AS discount_show_pv, SUM(day.dplsucc_pv) AS dplsucc_pv, SUM(day.complete_pv) AS complete_pv, SUM(day.install_pv) AS install_pv, SUM(day.activate_pv) AS activate_pv, MAX(ssp.name_alise) AS sspName, MAX(app.name) AS appName, MAX(app.os_type) AS osType, MAX(media.media_company_short) AS mediaName FROM data_ssp_slot_day AS day LEFT JOIN ssp_slot_info AS ssp ON day.ssp_slot_id = ssp.id LEFT JOIN ssp_app AS app ON app.id = ssp.app_id LEFT JOIN ssp_media AS media ON media.id = ssp.media_id
AND day.media_id = #{reqVO.mediaId}
AND day.app_id IN
#{id}
AND ssp.name_alise IN
#{name}
AND day.ssp_slot_id IN
#{id}
AND day.dsp_slot_id IN
#{id}
AND day.dsp_slot_code = #{reqVO.dspSlotCode}
AND app.os_type = #{reqVO.osType}
AND ssp.ad_scene = #{reqVO.adScene}
AND day.date BETWEEN REPLACE(#{reqVO.date[0]}, '-', '') AND REPLACE(#{reqVO.date[1]}, '-', '')
GROUP BY day.ssp_slot_id, day.date
ORDER BY day.date DESC

SELECT day.*
FROM data_ssp_slot_day AS day
WHERE day.id = #{id}

SELECT COALESCE(SUM(day.req_count), 0) AS reqCount
FROM data_ssp_slot_day AS day
WHERE day.ssp_slot_id = #{sspSlotId}
  AND day.date = #{time}

mapper.update:
UPDATE data_ssp_slot_day
SET income = #{income}, spend = #{spend}
WHERE ssp_slot_id = #{sspSlotId}
  AND dsp_slot_code = #{dspSlotCode}
  AND date = #{date}
